<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Support Contact Form</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --panel: #11182d;
        --panel-2: #18233d;
        --text: #e8eefc;
        --muted: #9fb0d0;
        --border: #2a375b;
        --accent: #76a9ff;
        --accent-strong: #4f8cff;
