        background: linear-gradient(180deg, rgba(17, 24, 45, 0.96), rgba(12, 18, 35, 0.96));
        border: 1px solid rgba(122, 146, 197, 0.2);
        border-radius: 24px;
        box-shadow: var(--shadow);
        overflow: hidden;
      }

      .support-header {
        padding: 32px 32px 0;
