      h1 {
        margin: 0 0 12px;
        font-size: clamp(1.8rem, 3vw, 2.5rem);
        letter-spacing: -0.03em;
      }

      .subtitle {
        margin: 0;
        color: var(--muted);
        line-height: 1.6;
      }

      form {
        padding: 28px 32px 32px;
      }

      .form-field {
        margin-bottom: 18px;
      }

      label {
        display: inline-block;
        margin-bottom: 8px;
        font-weight: 600;
      }

      .field-hint,
      .field-error {
        margin-top: 8px;
        font-size: 0.92rem;
        line-height: 1.4;
      }

      .field-hint {
        color: var(--muted);
      }

      .field-error {
        color: var(--error);
        min-height: 1.2em;
      }

      input {
        width: 100%;
        border-radius: 14px;
        border: 1px solid var(--border);
        background: rgba(8, 13, 26, 0.88);
        color: var(--text);
        padding: 14px 16px;
        font: inherit;
        transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
      }

      input::placeholder {
        color: #7687ad;
      }

      input:focus {
        outline: none;
        border-color: var(--accent);
        box-shadow: 0 0 0 4px rgba(118, 169, 255, 0.18);
      }

      input[aria-invalid="true"] {
