        padding: 14px 16px;
        font: inherit;
        transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
      }

      input::placeholder {
        color: #7687ad;
      }

      input:focus {
        outline: none;
        border-color: var(--accent);
        box-shadow: 0 0 0 4px rgba(118, 169, 255, 0.18);
      }

      input[aria-invalid="true"] {
        border-color: rgba(255, 123, 123, 0.9);
        box-shadow: 0 0 0 4px rgba(255, 123, 123, 0.12);
      }

      .actions {
        display: flex;
        justify-content: flex-end;
        margin-top: 28px;
