        }
      }
    </style>
  </head>
  <body>
    <main id="app" class="support-page" aria-label="Support contact form"></main>

    <script>
      const state = {
        fullName: "",
        email: "",
        phone: "",
        touched: {
          fullName: false,
          email: false,
          phone: false,
        },
        submitted: false,
      };

      const validators = {
        fullName(value) {
          return value.trim() ? "" : "Full name is required.";
        },
        email(value) {
          if (!value.trim()) return "Email address is required.";
          return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())
            ? ""
            : "Enter a valid email address.";
        },
        phone(value) {
          if (!value.trim()) return "";
          return /^[+]?[\d\s().-]{7,}$/.test(value.trim())
            ? ""
            : "Enter a valid phone number or leave this field blank.";
        },
      };

      const fieldMap = {
        "full-name": "fullName",
        "email-address": "email",
        "phone-number": "phone",
      };

      function escapeHtml(value) {
        return value
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");
      }

      function FormField({ id, label, type, placeholder, value, error, hint, required, autocomplete }) {
        return `
          <div class="form-field">
            <label for="${id}">${label}${required ? " *" : ""}</label>
            <input
              id="${id}"
              name="${id}"
              type="${type}"
              placeholder="${placeholder}"
              value="${escapeHtml(value)}"
              ${required ? "required" : ""}
              ${autocomplete ? `autocomplete="${autocomplete}"` : ""}
              aria-describedby="${id}-hint ${id}-error"
              aria-invalid="${error ? "true" : "false"}"
            />
            <div class="field-hint" id="${id}-hint">${hint || ""}</div>
            <div class="field-error" id="${id}-error" role="status" aria-live="polite">${error || ""}</div>
          </div>
        `;
      }

      function getErrors() {
        return {
          fullName: validators.fullName(state.fullName),
          email: validators.email(state.email),
          phone: validators.phone(state.phone),
        };
      }

      function SupportForm() {
        const errors = getErrors();
        const showError = (field) => state.touched[field] || state.submitted;

        return `
          <section class="support-card">
            <header class="support-header">
              <h1>Contact Support</h1>
              <p class="subtitle">Send us a message and we&apos;ll get back to you as soon as possible.</p>
            </header>
            <form id="contact-form" novalidate>
              ${FormField({
                id: "full-name",
                label: "Full name",
                type: "text",
                placeholder: "Jane Doe",
                value: state.fullName,
                error: showError("fullName") ? errors.fullName : "",
                hint: "",
                required: true,
                autocomplete: "name",
              })}
              ${FormField({
                id: "email-address",
                label: "Email address",
                type: "email",
                placeholder: "jane@example.com",
                value: state.email,
                error: showError("email") ? errors.email : "",
                hint: "",
                required: true,
                autocomplete: "email",
              })}
              ${FormField({
                id: "phone-number",
                label: "Phone number",
                type: "tel",
                placeholder: "+1 (555) 123-4567",
                value: state.phone,
                error: showError("phone") ? errors.phone : "",
                hint: "Optional. Use a format like +1 (555) 123-4567.",
                required: false,
                autocomplete: "tel",
              })}
              <div class="actions">
                <button type="submit">Submit</button>
              </div>
              <div class="status" id="form-status" aria-live="polite">
                ${state.submitted && !Object.values(errors).some(Boolean) ? "Message ready to send." : ""}
              </div>
            </form>
          </section>
        `;
      }

      function render() {
        document.getElementById("app").innerHTML = SupportForm();
        attachEvents();
        syncForm();
      }

      function attachEvents() {
        const form = document.getElementById("contact-form");
        Object.keys(fieldMap).forEach((id) => {
          const key = fieldMap[id];
          const input = document.getElementById(id);
          input.addEventListener("input", (event) => {
            state[key] = event.target.value;
            syncField(key);
            syncStatus();
          });
          input.addEventListener("blur", () => {
            state.touched[key] = true;
            syncField(key);
            syncStatus();
          });
        });

        form.addEventListener("submit", (event) => {
          event.preventDefault();
          state.submitted = true;
          state.touched.fullName = true;
          state.touched.email = true;
          state.touched.phone = true;
          syncForm();
        });
      }

      function syncField(key) {
        const inputId = Object.entries(fieldMap).find(([, mappedKey]) => mappedKey === key)?.[0];
        const input = document.getElementById(inputId);
        const errorId = `${inputId}-error`;
        const errorNode = document.getElementById(errorId);
        const errors = getErrors();
        const message = state.touched[key] || state.submitted ? errors[key] : "";

        if (!input || !errorNode) return;

        input.setAttribute("aria-invalid", message ? "true" : "false");
        errorNode.textContent = message;
      }

      function syncStatus() {
        const status = document.getElementById("form-status");
        const errors = getErrors();
        status.textContent = state.submitted && !Object.values(errors).some(Boolean)
          ? "Message ready to send."
          : "";
      }

      function syncForm() {
        const errors = getErrors();

        Object.values(fieldMap).forEach((key) => syncField(key));
        syncStatus();

        if (state.submitted && !Object.values(errors).some(Boolean)) {
          return;
        }
      }

      render();
    </script>
  </body>
</html>
